<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Invoice; use App\Models\Payment; use App\Services\Payments\PaymentService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class PaymentController extends Controller {
 public function index(Request $r){$q=Payment::where('company_id',$r->user()->company_id)->with('client','allocations.invoice');if($r->filled('search'))$q->where('payment_number','like','%'.$r->search.'%');return $q->latest('payment_date')->paginate($r->integer('per_page',20));}
 public function show(Request $r,Payment $payment){abort_unless($payment->company_id===$r->user()->company_id,404);return $payment->load('client','allocations.invoice');}
 public function store(Request $r,PaymentService $service){$data=$r->validate(['branch_id'=>['nullable','exists:branches,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Branch::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected branch is invalid.');}],'client_id'=>['nullable','exists:clients,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Client::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected client is invalid.');}],'payment_date'=>'nullable|date','amount'=>'required|numeric|min:0.01','method'=>'required|in:cash,bank,mpesa,airtel_money,tigopesa,halopesa,card,cheque,other','reference'=>'nullable|string|max:100','notes'=>'nullable|string','allocations'=>'required|array|min:1','allocations.*.invoice_id'=>'required|exists:invoices,id','allocations.*.amount'=>'required|numeric|min:0.01']);return response()->json($service->create($data,$r->user()),201);}
 public function destroy(Request $r,Payment $payment){abort_unless($payment->company_id===$r->user()->company_id,404);DB::transaction(function()use($payment){foreach($payment->allocations as $allocation){$invoice=$allocation->invoice()->lockForUpdate()->first();if($invoice){$paid=max(0,(float)$invoice->amount_paid-(float)$allocation->amount);$balance=max(0,(float)$invoice->total-$paid);$status=$paid<=0 ? (optional($invoice->due_date)->isPast() ? 'overdue' : 'issued') : ($balance<=0 ? 'paid' : 'partial');$invoice->update(['amount_paid'=>$paid,'balance'=>$balance,'status'=>$status]);}}$payment->allocations()->delete();$payment->delete();});return response()->noContent();}
 public function receivables(Request $r){$q=Invoice::where('company_id',$r->user()->company_id)->where('balance','>',0)->with('client')->latest('due_date');return $q->paginate($r->integer('per_page',30));}
}
